- Join Path: `superhero.publisher_id` -> `publisher.id` AND `superhero.gender_id` -> `gender.id`

## PHASE 5 — CONFIRMATION QUERIES

1. -- VERIFY CASE SENSITIVITY: Ensure no lowercase variants of 'Female' exist that would be missed by an exact match.
   SELECT DISTINCT gender FROM gender WHERE gender LIKE 'female' LIMIT 20;

2. -- VERIFY CASE SENSITIVITY: Ensure no lowercase variants of 'Marvel Comics' exist.
   SELECT DISTINCT publisher_name FROM publisher WHERE publisher_name LIKE 'marvel comics' LIMIT 20;

3. -- WHITESPACE CHECK: Check for leading or trailing spaces in the gender label.
   SELECT gender FROM gender WHERE gender LIKE '% Female%' OR gender LIKE '%Female %' LIMIT 20;

4. -- WHITESPACE CHECK: Check for leading or trailing spaces in the publisher name.
   SELECT publisher_name FROM publisher WHERE publisher_name LIKE '% Marvel Comics%' OR publisher_name LIKE '%Marvel Comics %' LIMIT 20;

5. -- DATA INTEGRITY: Confirm that all gender_id values in superhero table exist in the gender table.
   SELECT COUNT(*) FROM superhero WHERE gender_id NOT IN (SELECT id FROM gender) LIMIT 1;

6. -- DATA INTEGRITY: Confirm that all publisher_id values in superhero table exist in the publisher table.
   SELECT COUNT(*) FROM superhero WHERE publisher_id NOT IN (SELECT id FROM publisher) LIMIT 1;

7. -- ALTERNATIVE INTERPRETATION CHECK: Count total female heroes across all publishers to see if they form a logical denominator.
   SELECT COUNT(*) FROM superhero JOIN gender ON superhero.gender_id = gender.id WHERE gender.gender = 'Female' LIMIT 1;

8. -- NULL ANALYSIS: Verify the count of superheroes with no publisher assigned (expanding on Query 9).
   SELECT COUNT(*) FROM superhero WHERE publisher_id IS NULL LIMIT 1;

9. -- NULL ANALYSIS: Verify if any Marvel heroes have a NULL gender_id.
   SELECT COUNT(*) FROM superhero JOIN publisher ON superhero.publisher_id = publisher.id WHERE publisher.publisher_name = 'Marvel Comics' AND superhero.gender_id IS NULL LIMIT 1;

10. -- UNIQUNESS CHECK: Ensure there are no duplicate superhero IDs in the main table.
    SELECT COUNT(id), COUNT(DISTINCT id) FROM superhero LIMIT 1;

11. -- ENUM EXPLORATION: Check for any other gender values that might imply female (e.g., 'Woman').
    SELECT DISTINCT gender FROM gender WHERE gender NOT IN ('Male', 'Female', 'N/A') LIMIT 20;

12. -- JOIN VALIDATION: Verify the total count of Marvel heroes using a LEFT JOIN to ensure no records are dropped by an INNER JOIN.
    SELECT COUNT(*) FROM superhero LEFT JOIN publisher ON superhero.publisher_id = publisher.id WHERE publisher.publisher_name = 'Marvel Comics' LIMIT 1;

13. -- SCOPE VALIDATION: Verify the count of female Marvel heroes using a LEFT JOIN to ensure consistency.
    SELECT COUNT(*) FROM superhero LEFT JOIN publisher ON superhero.publisher_id = publisher.id LEFT JOIN gender ON superhero.gender_id = gender.id WHERE publisher.publisher_name = 'Marvel Comics' AND gender.gender = 'Female' LIMIT 1;

14. -- ALIGNMENT CHECK: Verify if any alignment values might restrict the definition of "hero".
    SELECT DISTINCT alignment FROM alignment LIMIT 20;

15. -- PUBLISHER LIST VALIDATION: Ensure there are no other publishers with 'Marvel' in the name besides 'Marvel Comics'.
    SELECT DISTINCT publisher_name FROM publisher WHERE publisher_name LIKE '%Marvel%' LIMIT 20;

